# -*- coding: utf-8 -*-
"""[Sinh, nạp và chia dữ liệu › Bộ sinh]
Làm gì   : Chứa kho ngữ liệu thô cho bộ sinh: cách xưng hô, người nhà, câu mẫu, triệu chứng
           và danh sách khuôn bệnh gốc.
Vào → Ra : — (chỉ chứa dữ liệu: XUNG_HO_NGUOI_LON, NGUOI_NHA, BENH, BENH_GOC... do bộ sinh
           và kho khuôn đọc)
Dùng bởi : bo_du_lieu/sinh_ca_da_benh_ly, do_luong/nguon_lap_cau,
           bo_du_lieu/chia_tap_theo_khuon, bo_du_lieu/kho_khuon, bo_du_lieu/kiem_khuon,
           bo_du_lieu/sinh_hoi_thoai_viet
Tên cũ   : ngu_lieu_viet.py (trước 27/11/2026) · Bản đồ: BAN_DO_MA_NGUON.md
────────────────────────────────────────────────────────────────────────
Kho ngữ liệu cho bộ sinh hội thoại khám bệnh Việt Nam.

Tách khỏi `sinh_hoi_thoai_viet.py` có chủ định: tệp này là DỮ LIỆU, tệp kia là
LUẬT. Đọc riêng dễ hơn, và khi cần thêm bệnh hay thêm cách nói thì chỉ sửa ở
đây, không đụng tới phần sinh.

VÌ SAO PHẢI TỰ DỰNG KHO NÀY.

Bộ dữ liệu của cuộc thi có dấu vết rõ là bản dịch từ một bộ hội thoại y khoa
tiếng Anh (Mỹ): pound/ounce nhiều hơn kg, Tylenol/Advil, "bệnh viện UIHC",
"phòng khám Sample" — xem `docs/ket-qua/dau-vet-nguon.md`. Ngôn ngữ là tiếng
Việt nhưng bối cảnh lâm sàng và lối nói thì không phải.

Hậu quả nằm đúng chỗ dự án quan tâm: hai thứ làm việc QUY GÁN khó nhất trong
tiếng Việt đều bị dưới đại diện trong một bản dịch từ tiếng Anh —

  1. LƯỢC CHỦ NGỮ. Tiếng Anh gần như luôn có chủ ngữ; tiếng Việt bỏ thoải mái:
     "Sốt hai hôm rồi", "Nôn từ tối qua". Người đọc suy ra chủ thể từ ngữ cảnh.
  2. TỪ CHỈ QUAN HỆ HỌ HÀNG LÀM ĐẠI TỪ. "cháu", "em", "con" vừa là cách người
     nói tự xưng, vừa là cách gọi người thứ ba. Câu "cháu nó sốt" và "cháu
     thấy mệt" có cùng chữ "cháu" nhưng khác chủ thể hoàn toàn.

Kho này dùng để sinh ra đúng hai hiện tượng đó, ở mật độ thật.

NGUYÊN TẮC CHỌN NỘI DUNG: bệnh, thuốc, đơn vị đo và cách xưng hô đều lấy theo
thực tế Việt Nam. Cân nặng kg, nhiệt độ đo C, thuốc là paracetamol/efferalgan/
hapacol chứ không phải Tylenol.
"""

