# NGƯỜI LỚN: người nhà chọn THEO lứa tuổi và giới của bệnh nhân (từ bác sĩ gọi
# bệnh nhân) — xem `sinh_hoi_thoai_viet._chon_nguoi_nha_nguoi_lon`. Thêm
# 11/09/2026, sau khi người dùng đọc một ca minh hoạ: "sao lại nhà em cái gì đây,
# không ai nói như này cả". Bảng cũ rút chung `NGUOI_NHA[3:]` cho mọi người lớn:
#   - bà nội, bà ngoại kể hộ bệnh nhân người lớn, kể cả người bác sĩ gọi "ông"
#     (184 ca huấn luyện)
#   - con gái tự xưng "cháu" trong khi bác sĩ gọi cô là "chị"
#   - "vợ" của một bệnh nhân bác sĩ gọi là "chị"
# `NGUOI_NHA` giữ nguyên (bộ thách thức cũ và test đọc nó), nhưng không còn dùng
# cho bệnh nhân người lớn.
LUA_TUOI_THEO_GOI = {"anh": "trẻ", "chị": "trẻ", "em": "trẻ",
                     "cô": "trung niên", "chú": "trung niên",
                     "bác": "cao tuổi", "ông": "cao tuổi", "bà": "cao tuổi"}
GIOI_THEO_GOI = {"anh": "nam", "chú": "nam", "ông": "nam",
                 "chị": "nữ", "cô": "nữ", "bà": "nữ"}      # "em", "bác": khong noi gioi
# Bác sĩ gọi vợ/chồng của bệnh nhân CÙNG vai vế với bệnh nhân.
VO_CHONG_GOI = {"anh": "chị", "chị": "anh", "em": "em", "chú": "cô", "cô": "chú",
                "bác": "bác", "ông": "bà", "bà": "ông"}
